import { Component, OnInit } from '@angular/core';
import {
  Ingredient,
  IngredientService
} from '../../services/ingredient.service';

@Component({
  selector: 'app-build-pizza',
  templateUrl: './build-pizza.component.html',
  styleUrls: ['./build-pizza.component.css']
})
export class BuildPizzaComponent implements OnInit {

  ingredients: Ingredient[] = [];

  selectedIngredients: Ingredient[] = [];

  totalPrice = 0;

  constructor(
    private ingredientService: IngredientService
  ) {}

  ngOnInit(): void {
    this.loadIngredients();
  }

  loadIngredients(): void {

    this.ingredientService.getIngredients().subscribe({

      next: (data) => {
        this.ingredients = data;
      },

      error: (error) => {
        console.error(
          'Failed to load ingredients:',
          error
        );
      }

    });

  }

  selectIngredient(ingredient: Ingredient): void {

    const index = this.selectedIngredients.findIndex(
      item => item.id === ingredient.id
    );

    if (index === -1) {

      this.selectedIngredients.push(ingredient);

    } else {

      this.selectedIngredients.splice(index, 1);

    }

    this.calculateTotal();

  }

  isSelected(ingredient: Ingredient): boolean {

    return this.selectedIngredients.some(
      item => item.id === ingredient.id
    );

  }

  calculateTotal(): void {

    this.totalPrice = this.selectedIngredients.reduce(
      (total, ingredient) =>
        total + ingredient.price,
      0
    );

  }

}
